374	// validateLoaded 对解码后的状态做基本不变量检查，违背即视为损坏。
375	func validateLoaded(fd *fileData) error {
376		switch {
377		case fd.Version != int(fileVersion):
378			return fmt.Errorf("%w: version %d in payload", ErrUnsupportedVersion, fd.Version)
379		case len(fd.Trajectory) == 0:
380			return fmt.Errorf("%w: empty trajectory", ErrCorrupt)
381		}
382		if err := validateConfig(fd.Config); err != nil {
383			// 配置不合法不可能由本版本写出。
384			return fmt.Errorf("%w: %v", ErrCorrupt, err)
385		}
386		// 保存的整条轨迹必须满足与导入时相同的时间规则：从初始位姿起
387		// 时间严格递增，且相邻位姿的真实间隔不超过 MaxInterval（恰好
388		// 等于上限合法）。任何一处相等、倒退或超限都使按时间查询失去
389		// 可靠的先后依据，整份文件按损坏拒绝。间隔按真实差值判断：前
390		// 一时间接近 math.MinInt64 而后一时间为非负时，有符号减法会
391		// 溢出回绕成负数，把超限的巨大缺口放过去；此处已保证递增，真
392		// 实差值落在 [1, 2^64-1]，用无符号减法取精确的数学差值再与上
393		// 限比较（MaxInterval 已校验为正）。
394		for i := 1; i < len(fd.Trajectory); i++ {
395			prev, cur := fd.Trajectory[i-1].Time, fd.Trajectory[i].Time
396			if cur <= prev {
397				return fmt.Errorf("%w: trajectory time at pose %d is not strictly increasing", ErrCorrupt, i)
398			}
399			if uint64(cur)-uint64(prev) > uint64(fd.Config.MaxInterval) {
400				return fmt.Errorf("%w: trajectory interval between poses %d and %d exceeds max interval", ErrCorrupt, i-1, i)
401			}
402		}
403		// 新格式的逐帧依据必须与轨迹（除初始位姿外）一一对应；旧文件缺省
404		// 该字段（解码为 nil），数量为 0。
405		if len(fd.Sources) != 0 && len(fd.Sources) != len(fd.Trajectory)-1 {
406			return fmt.Errorf("%w: frame sources length %d for %d frames", ErrCorrupt, len(fd.Sources), len(fd.Trajectory)-1)
407		}
408		seenIDs := make(map[string]struct{}, len(fd.Landmarks))
409		for _, lm := range fd.Landmarks {
410			if lm.ID == "" {
411				return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
412			}
413			if _, dup := seenIDs[lm.ID]; dup {
414				return fmt.Errorf("%w: duplicate landmark %s", ErrCorrupt, lm.ID)
415			}
416			seenIDs[lm.ID] = struct{}{}
417			if len(lm.Occurrences) == 0 {
418				// 兼容旧布局：平铺字段表示第 1 次出现。
419				if lm.Count < 1 || !isFinite(lm.X) || !isFinite(lm.Y) {
420					return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
421				}
422				if lm.LegacyCount < 0 || lm.LegacyCount > lm.Count {
423					return fmt.Errorf("%w: invalid legacy count for landmark %s", ErrCorrupt, lm.ID)
424				}
425				if lm.LegacyCount > 0 && (!isFinite(lm.LegacyMX) || !isFinite(lm.LegacyMY)) {
426					return fmt.Errorf("%w: invalid legacy mean for landmark %s", ErrCorrupt, lm.ID)
427				}
428				continue
429			}
430			activeCount := 0
431			for i, oj := range lm.Occurrences {
432				if oj.Number != i+1 || oj.Count < 1 || !isFinite(oj.X) || !isFinite(oj.Y) {
433					return fmt.Errorf("%w: invalid occurrence for landmark %s", ErrCorrupt, lm.ID)
434				}
435				if oj.LegacyCount < 0 || oj.LegacyCount > oj.Count {
436					return fmt.Errorf("%w: invalid legacy count for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
437				}
438				if oj.LegacyCount > 0 && (!isFinite(oj.LegacyMX) || !isFinite(oj.LegacyMY)) {
439					return fmt.Errorf("%w: invalid legacy mean for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
440				}
441				if oj.Active {
442					activeCount++
443					if i != len(lm.Occurrences)-1 {
444						return fmt.Errorf("%w: active occurrence %d of landmark %s is not the latest", ErrCorrupt, oj.Number, lm.ID)
445					}
446				} else if oj.InvalidReason == "" {
447					return fmt.Errorf("%w: invalidated occurrence %d of landmark %s lacks reason", ErrCorrupt, oj.Number, lm.ID)
448				}
449				// 出现编号即先后次序，各次出现接纳观测的时间范围必须与之
450				// 相容，否则同一观测可能同时属于两次出现（归属校验只确认能
451				// 归入某一次，不排除同时归入两次）。已失效且首次观测时间
452				// 已知的出现，首次观测不能晚于失效；下一次出现的首次观测
453				// 必须严格晚于上一次的失效时间——首次观测与失效两个端点都
454				// 接纳所在时刻的观测，相等即重叠。第 2 次及以后的出现必定
455				// 在上一次失效之后由本包创建，首次观测时间必须已知；只有
456				// 旧文件的第 1 次出现允许未知（无下界，不把零当作起点）。
457				// 这些检查针对保存的出现记录本身，与重叠范围内当前是否有
458				// 观测无关。
459				if !oj.Active && oj.HasFirstSeen && oj.FirstSeenTime > oj.InvalidTime {
460					return fmt.Errorf("%w: occurrence %d of landmark %s first seen at %d after invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, oj.InvalidTime)
461				}
462				if i > 0 {
463					if !oj.HasFirstSeen {
464						return fmt.Errorf("%w: occurrence %d of landmark %s lacks first seen time", ErrCorrupt, oj.Number, lm.ID)
465					}
466					// 上一次出现必已失效（仍有效且非最后一次已在上面拒绝）。
467					if prev := lm.Occurrences[i-1]; oj.FirstSeenTime <= prev.InvalidTime {
468						return fmt.Errorf("%w: occurrence %d of landmark %s starts at %d before previous invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, prev.InvalidTime)
469					}
470				}
471			}
472			if activeCount > 1 {
473				return fmt.Errorf("%w: multiple active occurrences for landmark %s", ErrCorrupt, lm.ID)
474			}
475		}
476		// 各路标历次出现的时间边界：来源帧的观测归属核对与校正记录路标列表
477		// 核对共用同一份边界、同一套归属规则（见 occurrence.go）。旧文件缺省
478		// sources（解码为 nil）时不构建，两处核对都不进行。
479		var bounds map[string][]occurrenceWindow
480		if len(fd.Sources) != 0 {
481			bounds = make(map[string][]occurrenceWindow, len(fd.Landmarks))
482			for _, lm := range fd.Landmarks {
483				bounds[lm.ID] = occurrenceWindowsOf(lm)
484			}
485		}
486		// 校验每条带逐帧依据的观测来源：观测路标必须存在，且所在帧时间必须
487		// 落入该路标某一次出现的时间边界（共享规则见 occurrence.go）。旧出现
488		// 已失效不代表其历史观测无效；同一标识两次出现之间（如 200 失效、
489		// 300 再现时的 250 帧）的观测没有归属，按损坏拒绝。null 帧来自缺少
490		// 逐帧依据的旧地图，其观测不在这里（也无法）核验；旧版平铺路标视为
491		// 一次无边界的有效出现，因此旧地图后来追加的来源帧仍按此规则检查。
492		if len(fd.Sources) != 0 {
493			// 归属校验的同时按（路标，出现编号）统计来源观测条数：每条观测
494			// 各算一次，同帧重复观测同一标识不去重，空观测帧不计。null 帧
495			// 缺少逐帧依据，其贡献已固定在出现的旧观测计数中，不在此统计，
496			// 也不能按帧数猜测。
497			tallies := make(map[string]map[int]int, len(fd.Landmarks))
498			for k, src := range fd.Sources {
499				if src == nil {
500					continue // 旧地图帧：无逐帧依据，不要求补齐归属
501				}
502				t := fd.Trajectory[k+1].Time
503				for _, ob := range src.Observations {
504					wins, ok := bounds[ob.ID]
505					if !ok {
506						return fmt.Errorf("%w: observation of unknown landmark %s at frame time %d", ErrCorrupt, ob.ID, t)
507					}
508					num := occurrenceNumberAt(wins, t)
509					if num == 0 {
510						return fmt.Errorf("%w: observation of landmark %s at frame time %d belongs to no occurrence", ErrCorrupt, ob.ID, t)
511					}
512					c := tallies[ob.ID]
513					if c == nil {
514						c = make(map[int]int, 1)
515						tallies[ob.ID] = c
516					}
517					c[num]++
518				}
519			}
520			// 每次出现记录的观测次数必须等于归属该次出现的来源观测条数加上
521			// 该次出现已保存的旧观测贡献：偏多或偏少都是文件损坏。各次出现
522			// 分别核对，不能用另一次出现的观测补足；已失效的旧出现同样核对，
523			// 不因它不再参与区域查询而跳过。回环校正只改位置不改已接受观测
524			// 次数，正常校正后保存的文件仍满足此不变量。
525			for _, lm := range fd.Landmarks {
526				if len(lm.Occurrences) == 0 {
527					// 旧版平铺路标即第 1 次出现。
528					if got := tallies[lm.ID][1] + lm.LegacyCount; got != lm.Count {
529						return fmt.Errorf("%w: landmark %s records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, lm.Count, got)
530					}
531					continue
532				}
533				for _, oj := range lm.Occurrences {
534					if got := tallies[lm.ID][oj.Number] + oj.LegacyCount; got != oj.Count {
535						return fmt.Errorf("%w: landmark %s occurrence %d records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, oj.Number, oj.Count, got)
536					}
537				}
538			}
539	
540			// 位置核对：次数相符只说明观测“条数”对得上，还必须核对保存的路标
541			// 位置确实是这些观测依据当前保存位姿重放后的等权平均。每条来源观测
542			// 按所在帧当前保存的位姿转换到地图坐标，按帧时间升序、同帧按输入
543			// 次序，归入各自出现分别重放；同帧对同一标识的多条观测各自参与，
544			// 空观测帧不增加贡献。转换、接纳、增量平均与计数全部复用导入/校正
545			// 的同一规则（见 aggregate.go），旧文件固定旧贡献（LegacyCount 次
546			// 平均）作为聚合起点——不能当成零，也不能用缺少依据的帧数代替。
547			// 回环校正后保存的文件按当前轨迹重放即得到当前位置，不要求等于校正
548			// 记录里的历史快照；各次出现分别核对，已失效的出现同样核对。合并
549			// 距离只是导入/校正时的接纳门槛，不是保存位置偏差的容许范围：重放
550			// 中出现非有限结果或距离冲突，或最终平均位置与保存位置不完全一致，
551			// 都按损坏拒绝。纯旧文件没有 sources、null 旧帧没有依据，均不重放。
552			type posKey struct {
553				id  string
554				num int
555			}
556			posAggs := make(map[posKey]*observationAgg, len(fd.Landmarks))
557			seedPosAgg := func(id string, num, legacyCount int, lx, ly float64) {
558				a := &observationAgg{}
559				if legacyCount > 0 {
560					a.seed(legacyCount, lx, ly)
561				}
562				posAggs[posKey{id: id, num: num}] = a
563			}
564			for _, lm := range fd.Landmarks {
565				if len(lm.Occurrences) == 0 {
566					// 旧版平铺路标即第 1 次出现。
567					seedPosAgg(lm.ID, 1, lm.LegacyCount, lm.LegacyMX, lm.LegacyMY)
568					continue
569				}
570				for _, oj := range lm.Occurrences {
571					seedPosAgg(lm.ID, oj.Number, oj.LegacyCount, oj.LegacyMX, oj.LegacyMY)
572				}
573			}
574			for k, src := range fd.Sources {
575				if src == nil {
576					continue // 旧地图帧：无逐帧依据，其贡献固定在旧贡献起点中
577				}
578				pose := fd.Trajectory[k+1]
579				for _, ob := range src.Observations {
580					// 归属（存在性与时间边界）已在上面校验，num 必非 0。
581					num := occurrenceNumberAt(bounds[ob.ID], pose.Time)
582					a := posAggs[posKey{id: ob.ID, num: num}]
583					switch a.admit(pose, ob, fd.Config.MergeDistance) {
584					case obsNonFinite:
585						return fmt.Errorf("%w: replayed observation of landmark %s occurrence %d at frame time %d is non-finite", ErrCorrupt, ob.ID, num, pose.Time)
586					case obsConflict:
587						return fmt.Errorf("%w: replayed observation of landmark %s occurrence %d at frame time %d violates merge distance", ErrCorrupt, ob.ID, num, pose.Time)
588					}
589				}
590			}
591			checkPosition := func(id string, num int, x, y float64) error {
592				a := posAggs[posKey{id: id, num: num}]
593				// 次数核对已保证 a.count 与记录次数一致（含旧贡献起点），这里只
594				// 核对位置：保存位置必须与按依据重放出的等权平均完全一致。
595				if a.x != x || a.y != y {
596					return fmt.Errorf("%w: landmark %s occurrence %d is saved at (%v,%v) but its observations replay to (%v,%v)", ErrCorrupt, id, num, x, y, a.x, a.y)
597				}
598				return nil
599			}
600			for _, lm := range fd.Landmarks {
601				if len(lm.Occurrences) == 0 {
602					if err := checkPosition(lm.ID, 1, lm.X, lm.Y); err != nil {
603						return err
604					}
605					continue
606				}
607				for _, oj := range lm.Occurrences {
608					if err := checkPosition(lm.ID, oj.Number, oj.X, oj.Y); err != nil {
609						return err
610					}
611				}
612			}
613		}
614		segIDs := make(map[string]struct{}, len(fd.Segments))
615		for _, sg := range fd.Segments {
616			if sg.ID == "" || sg.Hash == "" {
617				return fmt.Errorf("%w: invalid segment record", ErrCorrupt)
618			}
619			if _, dup := segIDs[sg.ID]; dup {
620				return fmt.Errorf("%w: duplicate segment %s", ErrCorrupt, sg.ID)
621			}
622			segIDs[sg.ID] = struct{}{}
623		}
624		corrIDs := make(map[string]struct{}, len(fd.Corrections))
625		// corrOccKey 标识校正范围内被观测涉及的某个路标某一次出现。
626		type corrOccKey struct {
627			id  string
628			num int
629		}
630		for _, cr := range fd.Corrections {
631			if cr.ID == "" || cr.Anchor > cr.EndTime {
632				return fmt.Errorf("%w: invalid correction record", ErrCorrupt)
633			}
634			// 锚点与结束时间必须准确命中已导入帧：trajectory[0] 是初始位姿，
635			// 不是可校正的帧，也不能用相邻帧的时间代替。轨迹时间已在前面
636			// 校验为严格递增，命中即唯一。
637			anchorIdx, endIdx := -1, -1
638			for j := 1; j < len(fd.Trajectory); j++ {
639				if fd.Trajectory[j].Time == cr.Anchor {
640					anchorIdx = j
641				}
642				if fd.Trajectory[j].Time == cr.EndTime {
643					endIdx = j
644				}
645			}
646			if anchorIdx < 0 || endIdx < 0 {
647				return fmt.Errorf("%w: correction %s range does not hit imported frames", ErrCorrupt, cr.ID)
648			}
649			// 记录必须恰好覆盖 [anchor, end] 内的每一帧：位姿条目数量等于
650			// 范围内帧数，按轨迹时间次序一一对应，且同一份前后位姿的时间
651			// 相同并就是对应帧的时间。缺失、重复、错序、额外加入范围外的
652			// 帧，或把前后时间写成两个不同帧，都使记录不能完整描述声明的
653			// 范围，按损坏拒绝。这里只核对覆盖的帧及时间：快照中的位置、
654			// 朝向和方差是提交时的历史值，不要求等于当前轨迹（后来对相同
655			// 范围再校正、或之后导入新帧，都不影响既有记录的合法性）。
656			if len(cr.Poses) != endIdx-anchorIdx+1 {
657				return fmt.Errorf("%w: correction %s does not cover every frame in its range", ErrCorrupt, cr.ID)
658			}
659			for i, pc := range cr.Poses {
660				ft := fd.Trajectory[anchorIdx+i].Time
661				if pc.Before.Time != ft || pc.After.Time != ft {
662					return fmt.Errorf("%w: correction %s pose entry %d does not match frame time %d", ErrCorrupt, cr.ID, i, ft)
663				}
664				if !finitePose(pc.Before) || !finitePose(pc.After) {
665					return fmt.Errorf("%w: correction %s has non-finite pose", ErrCorrupt, cr.ID)
666				}
667			}
668			// 以下两项核对都只针对范围内逐帧依据完整的校正：范围内任一来源
669			// 帧为 null 旧帧时保留旧文件的既有打开规则，不推测运动方差、也
670			// 不把未知贡献当成零；纯旧文件缺省 sources（长度为 0，bounds 同
671			// 时为 nil）时所有记录都不核对。同一文件中其余依据完整的记录不
672			// 受含旧帧记录影响，仍逐一核对。
673			fullyBased := len(fd.Sources) != 0
674			if fullyBased {
675				for k := anchorIdx - 1; k <= endIdx-1; k++ {
676					if fd.Sources[k] == nil {
677						fullyBased = false
678						break
679					}
680				}
681			}
682			if fullyBased {
683				// 校正后方差核对：锚点帧的校正后方差必须等于该次提交的目标
684				// 方差；其后每帧在目标方差上，按时间顺序累加锚点之后至该帧
685				// 的原运动方差。锚点自身进入该帧的运动方差不再加一次，也不
686				// 能以校正前方差作为起点；累计范围以本记录自己的锚点与结束
687				// 时间为准，后来对重叠范围的再校正与之后追加的帧都不属于本
688				// 记录。目标方差或参与累计的运动方差为负/非有限、累计结果非
689				// 有限，或与保存的校正后方差不完全一致，都按损坏拒绝整份文
690				// 件——每一帧逐一核对，不能只凭锚点与末帧正确就接受中间错误
691				// 的记录；目标方差与运动方差全为零的合法校正同样逐帧通过。
692				accum := cr.Target.Variance
693				if !isFinite(accum) || accum < 0 {
694					return fmt.Errorf("%w: correction %s target variance is negative or non-finite", ErrCorrupt, cr.ID)
695				}
696				for i, pc := range cr.Poses {
697					if i > 0 {
698						// 记录内第 i 帧位于轨迹下标 anchorIdx+i；进入它的运
699						// 动方差在来源 sources[anchorIdx+i-1]（i=1 即锚点之
700						// 后第一帧），锚点自身的来源 sources[anchorIdx-1] 不
701						// 参与累计。
702						mv := fd.Sources[anchorIdx+i-1].MoveVariance
703						if !isFinite(mv) || mv < 0 {
704							return fmt.Errorf("%w: correction %s accumulates negative or non-finite motion variance at frame time %d", ErrCorrupt, cr.ID, pc.After.Time)
705						}
706						accum += mv
707						if !isFinite(accum) {
708							return fmt.Errorf("%w: correction %s corrected variance accumulates to non-finite value at frame time %d", ErrCorrupt, cr.ID, pc.After.Time)
709						}
710					}
711					if pc.After.Variance != accum {
712						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected variance %v but target variance %v and the motion variances after the anchor accumulate to %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.Variance, cr.Target.Variance, accum)
713					}
714				}
715			}
716			for _, lc := range cr.Landmarks {
717				if lc.ID == "" {
718					return fmt.Errorf("%w: correction %s has empty landmark id", ErrCorrupt, cr.ID)
719				}
720				if lc.Occurrence < 0 || !isFinite(lc.Before.X) || !isFinite(lc.Before.Y) ||
721					!isFinite(lc.After.X) || !isFinite(lc.After.Y) ||
722					lc.Before.Count < 1 || lc.After.Count < 1 {
723					return fmt.Errorf("%w: correction %s has invalid landmark change", ErrCorrupt, cr.ID)
724				}
725			}
726			// 路标列表必须恰好描述记录范围（锚点帧到结束帧，两端包含；之后
727			// 追加的帧不属于范围）内逐帧观测实际涉及的路标出现：范围内被观测
728			// 到的每个（路标，出现编号）必须恰好有一条前后记录，同一次出现被
729			// 多帧或同帧多条观测涉及也只记一条；少记、多记、重复、或把出现
730			// 编号改指该范围没有涉及的另一出现，都按损坏拒绝整份文件，而不是
731			// 只看条目里的坐标与次数是否合法。归属沿用与来源校验相同的时间边
732			// 界规则：同一标识失效后再现属于不同出现，即使位置相同也分别对应；
733			// 已失效的旧出现只要范围内（含失效时刻）有它的观测就必须在列表
734			// 中，不因当前区域查询不再返回它而被排除；范围外帧（如记录之后
735			// 才再现的新出现）的观测不计入。范围内没有任何路标观测时列表必须
736			// 为空，非空即损坏。仅对范围内逐帧依据完整的校正做此核对：范围内
737			// 含 null 旧帧的校正缺少逐帧依据，保留旧地图的既有打开规则，不凭
738			// 推测要求补造观测。
739			if bounds != nil && fullyBased {
740				want := make(map[corrOccKey]struct{})
741				for j := anchorIdx; j <= endIdx; j++ {
742					t := fd.Trajectory[j].Time
743					for _, ob := range fd.Sources[j-1].Observations {
744						// 归属已在上方的来源校验中确认（路标存在、必有唯一
745						// 接纳出现），这里同样计算以保持两处规则一致。
746						want[corrOccKey{id: ob.ID, num: occurrenceNumberAt(bounds[ob.ID], t)}] = struct{}{}
747					}
748				}
749				got := make(map[corrOccKey]struct{}, len(cr.Landmarks))
750				for _, lc := range cr.Landmarks {
751					num := lc.Occurrence
752					if num == 0 {
753						num = 1 // 更早版本写出的校正记录不带编号，按第 1 次出现解释
754					}
755					wins, ok := bounds[lc.ID]
756					if !ok || num < 1 || num > len(wins) {
757						return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d not touched by its range", ErrCorrupt, cr.ID, lc.ID, num)
758					}
759					key := corrOccKey{id: lc.ID, num: num}
760					if _, dup := got[key]; dup {
761						return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d more than once", ErrCorrupt, cr.ID, lc.ID, num)
762					}
763					got[key] = struct{}{}
764				}
765				for key := range want {
766					if _, ok := got[key]; !ok {
767						return fmt.Errorf("%w: correction %s misses landmark %s occurrence %d observed in its range", ErrCorrupt, cr.ID, key.id, key.num)
768					}
769				}
770				for key := range got {
771					if _, ok := want[key]; !ok {
772						return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d with no observation in its range", ErrCorrupt, cr.ID, key.id, key.num)
773					}
774				}
775			}
776			if _, dup := corrIDs[cr.ID]; dup {
777				return fmt.Errorf("%w: duplicate correction %s", ErrCorrupt, cr.ID)
778			}
779			corrIDs[cr.ID] = struct{}{}
780		}
781		// 路标记录按标识索引，供失效记录与出现历史的交叉核对使用。
782		lmByID := make(map[string]*landmarkJSON, len(fd.Landmarks))
783		for i := range fd.Landmarks {
784			lmByID[fd.Landmarks[i].ID] = &fd.Landmarks[i]
785		}
786		invalIDs := make(map[string]struct{}, len(fd.Invalidations))
787		// invalTriples 记录每条失效操作实际引用的（操作标识，路标，出现编号）
788		// 三元组，供反向核对：每个已失效出现都必须是某条操作记录里的实际条目。
789		type invalTriple struct {
790			op  string
791			lm  string
792			num int
793		}
794		invalTriples := make(map[invalTriple]struct{}, len(fd.Invalidations))
795		for _, iv := range fd.Invalidations {
796			if iv.ID == "" || iv.Reason == "" || iv.Hash == "" || len(iv.Landmarks) == 0 {
797				return fmt.Errorf("%w: invalid invalidation record", ErrCorrupt)
798			}
799			if _, dup := invalIDs[iv.ID]; dup {
800				return fmt.Errorf("%w: duplicate invalidation %s", ErrCorrupt, iv.ID)
801			}
802			invalIDs[iv.ID] = struct{}{}
803			lmSeen := make(map[string]struct{}, len(iv.Landmarks))
804			for _, l := range iv.Landmarks {
805				if l.ID == "" || l.Occurrence < 1 {
806					return fmt.Errorf("%w: invalid invalidation landmark entry", ErrCorrupt)
807				}
808				if _, dup := lmSeen[l.ID]; dup {
809					return fmt.Errorf("%w: invalidation %s lists %s twice", ErrCorrupt, iv.ID, l.ID)
810				}
811				lmSeen[l.ID] = struct{}{}
812			}
813			// 交叉核对：成功失效结果里的每个（路标标识，出现编号）必须准确
814			// 指向该路标历史中同编号的那次出现，不能改指同一路标的其他出现，
815			// 也不能因为路标后来再次出现就把旧结果指向最新记录。被指出现必须
816			// 已经失效，且其上记录的失效操作标识、失效时间、失效原因都与这条
817			// 操作记录一致——时间与原因各自再合理也不够，实际由另一条操作撤下
818			// 时不能仅凭相同时间/原因认可。旧版平铺路标视为第 1 次有效出现，
819			// 不可能被失效记录引用（引用即损坏）。一条操作同时撤下多个路标时，
820			// 任意一个条目不满足对应关系都拒绝打开整个文件。
821			for _, l := range iv.Landmarks {
822				lm := lmByID[l.ID]
823				if lm == nil {
824					return fmt.Errorf("%w: invalidation %s result points to unknown landmark %s", ErrCorrupt, iv.ID, l.ID)
825				}
826				if len(lm.Occurrences) == 0 {
827					return fmt.Errorf("%w: invalidation %s result points to flat legacy landmark %s which has no invalidated occurrence", ErrCorrupt, iv.ID, l.ID)
828				}
829				if l.Occurrence > len(lm.Occurrences) {
830					return fmt.Errorf("%w: invalidation %s result points to landmark %s occurrence %d which does not exist", ErrCorrupt, iv.ID, l.ID, l.Occurrence)
831				}
832				// 出现编号连续性已在上方路标校验中强制，该下标处编号即 l.Occurrence。
833				oj := lm.Occurrences[l.Occurrence-1]
834				if oj.Active {
835					return fmt.Errorf("%w: invalidation %s result points to landmark %s occurrence %d which is still active", ErrCorrupt, iv.ID, l.ID, l.Occurrence)
836				}
837				if oj.InvalidOpID != iv.ID || oj.InvalidTime != iv.Time || oj.InvalidReason != iv.Reason {
838					return fmt.Errorf("%w: invalidation %s result for landmark %s occurrence %d does not match its saved invalidation (op %q, time %d, reason %q)", ErrCorrupt, iv.ID, l.ID, l.Occurrence, oj.InvalidOpID, oj.InvalidTime, oj.InvalidReason)
839				}
840				invalTriples[invalTriple{op: iv.ID, lm: l.ID, num: l.Occurrence}] = struct{}{}
841			}
842		}
843		// 反向核对：每个已失效出现都必须能在失效操作序列中找到引用同一（操作，
844		// 路标，出现编号）三元组的条目。正向核对已保证被引用出现的失效时间与
845		// 原因和引用方一致；此处堵住另一方向的矛盾：出现凭空携带失效信息、
846		// 声称撤下它的操作记录实际指向另一次出现，或两次出现声称被同一操作
847		// 撤下（一次操作对同一路标只会撤下当时唯一的有效出现）。旧地图没有
848		// 失效操作时，平铺路标视为有效、不携带失效信息，不会触发；旧地图后来
849		// 产生的失效操作同样在上述核对之列，不要求补齐原本缺失的逐帧观测。
850		for _, lm := range fd.Landmarks {
851			for _, oj := range lm.Occurrences {
852				if oj.Active {
853					continue
854				}
855				if _, ok := invalTriples[invalTriple{op: oj.InvalidOpID, lm: lm.ID, num: oj.Number}]; !ok {
856					return fmt.Errorf("%w: landmark %s occurrence %d is marked invalidated by operation %q which does not record that invalidation", ErrCorrupt, lm.ID, oj.Number, oj.InvalidOpID)
857				}
858			}
859		}
860		return nil
861	}
862	
863	func finitePose(p Pose) bool {
864		return isFinite(p.X) && isFinite(p.Y) && isFinite(p.Heading) && isFinite(p.Variance)
865	}
866	
867	// canonicalCorrectionHash 计算一次校正请求（锚点时间 + 目标位姿）的
868	// 确定性指纹，用于同标识重复提交判定。直接按 IEEE-754 位编码。
869	func canonicalCorrectionHash(anchor int64, tgt CorrectionTarget) string {
870		h := sha256.New()
871		var b [8]byte
872		binary.BigEndian.PutUint64(b[:], uint64(anchor))
873		h.Write(b[:])
874		for _, v := range []float64{tgt.X, tgt.Y, tgt.Heading, tgt.Variance} {
875			binary.BigEndian.PutUint64(b[:], math.Float64bits(v))
876			h.Write(b[:])
877		}
878		return fmt.Sprintf("%x", h.Sum(nil))
879	}
880	
881	// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
882	func (m *Map) saveExclusive() error {
883		data, err := encodeFile(m.state)
884		if err != nil {
885			return err
886		}
887		f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
888		if err != nil {
889			return err
890		}
891		return writeAndClose(f, data, m.path)
892	}
893	
894	// saveReplace 用同目录临时文件 + rename 原子替换现有文件。
895	func (m *Map) saveReplace() (err error) {
896		data, err := encodeFile(m.state)
897		if err != nil {
898			return err
899		}
900		dir, base := filepath.Split(m.path)
901		if dir == "" {
902			dir = "."
903		}
904		f, err := os.CreateTemp(dir, base+".tmp-*")
905		if err != nil {
906			return err
907		}
908		tmpName := f.Name()
909		// 任何失败路径都尽力清理临时文件。
910		defer func() {
911			if err != nil {
912				_ = os.Remove(tmpName)
913			}
914		}()
915		if err = writeAndClose(f, data, tmpName); err != nil {
916			return err
917		}
918		if err = os.Rename(tmpName, m.path); err != nil {
919			return err
920		}
921		return nil
922	}
923	
924	func writeAndClose(f *os.File, data []byte, name string) (err error) {
925		defer func() {
926			if cerr := f.Close(); err == nil {
927				err = cerr
928			}
929		}()
930		if _, err = f.Write(data); err != nil {
931			return err
932		}
933		if err = f.Sync(); err != nil {
934			return err
935		}
936		return nil
937	}
938	
939	// canonicalHash 计算一批帧的确定性指纹，用于重复导入判定。直接按
940	// IEEE-754 位编码，NaN/Inf 也有稳定表示，不依赖 JSON 对其不支持的问题。
941	func canonicalHash(frames []Frame) string {
942		h := sha256.New()
943		var lenBuf [4]byte
944		var numBuf [8]byte
945		putU32 := func(v uint32) {
946			binary.BigEndian.PutUint32(lenBuf[:], v)
947			h.Write(lenBuf[:])
948		}
949		putU64 := func(v uint64) {
950			binary.BigEndian.PutUint64(numBuf[:], v)
951			h.Write(numBuf[:])
952		}
953		putStr := func(s string) {
954			putU32(uint32(len(s)))
955			h.Write([]byte(s))
956		}
957	
958		putU32(uint32(len(frames)))
959		for _, fr := range frames {
960			putU64(uint64(fr.Time))
961			putU64(math.Float64bits(fr.DX))
962			putU64(math.Float64bits(fr.DY))
963			putU64(math.Float64bits(fr.DHeading))
964			putU64(math.Float64bits(fr.MoveVariance))
965			putU32(uint32(len(fr.Observations)))
966			for _, ob := range fr.Observations {
967				putStr(ob.ID)
968				putU64(math.Float64bits(ob.X))
969				putU64(math.Float64bits(ob.Y))
970			}
971		}
972		return fmt.Sprintf("%x", h.Sum(nil))
973	}
974

