13	func buildTimedMap(t *testing.T, path string, cfg Config, times ...int64) {
14		t.Helper()
15		m, err := Create(path, cfg)
16		if err != nil {
17			t.Fatal(err)
18		}
19		frames := make([]Frame, len(times))
20		for i, tm := range times {
21			frames[i] = Frame{Time: tm, DX: 1}
22		}
23		if len(frames) > 0 {
24			if _, err := m.ImportSegment(Segment{ID: "s1", Frames: frames}); err != nil {
25				t.Fatal(err)
26			}
27		}
28		if err := m.Close(); err != nil {
29			t.Fatal(err)
30		}
31	}
32	
33	// setTrajectoryTimes 重写文件中保存的轨迹时间（长度不变）并重算校验和。
34	func setTrajectoryTimes(t *testing.T, path string, times ...int64) {
35		t.Helper()
36		fd := readFileData(t, path)
37		if len(fd.Trajectory) != len(times) {
38			t.Fatalf("trajectory has %d poses, want %d", len(fd.Trajectory), len(times))
39		}
40		for i, tm := range times {
41			fd.Trajectory[i].Time = tm
42		}
43		writeFileDataRaw(t, path, &fd)
44	}
45	
46	// 打开时轨迹时间相等、倒退或间隔超限都按 ErrCorrupt 拒绝，不返回地图
47	// 对象，且原文件内容保持不变。
48	func TestOpenRejectsBadTrajectoryTimes(t *testing.T) {
49		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
50		cases := []struct {
51			name  string
52			times []int64
53		}{
54			{"equal within segment", []int64{0, 100, 100}},
55			{"backwards within segment", []int64{0, 200, 100}},
56			{"equal to initial", []int64{0, 0, 100}},
57			{"interval exceeded", []int64{0, 100, 1101}},
58			{"interval exceeded from initial", []int64{0, 1001, 1002}},
59		}
60		for _, tc := range cases {
61			t.Run(tc.name, func(t *testing.T) {
62				path := filepath.Join(t.TempDir(), "m.pose")
63				buildTimedMap(t, path, cfg, 100, 200)
64				setTrajectoryTimes(t, path, tc.times...)
65				before, err := os.ReadFile(path)
66				if err != nil {
67					t.Fatal(err)
68				}
69				m, err := Open(path)
70				if !errors.Is(err, ErrCorrupt) {
71					t.Fatalf("err = %v, want ErrCorrupt", err)
72				}
73				if m != nil {
74					t.Fatalf("map = %v, want nil", m)
75				}
76				after, err := os.ReadFile(path)
77				if err != nil {
78					t.Fatal(err)
79				}
80				if string(before) != string(after) {
81					t.Fatal("file modified by rejected Open")
82				}
83			})
84		}
85	}
86	
87	// 间隔恰好等于 MaxInterval 合法；仅含初始位姿的地图也正常打开。
88	func TestOpenAcceptsBoundaryTrajectoryTimes(t *testing.T) {
89		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
90		path := filepath.Join(t.TempDir(), "m.pose")
91		buildTimedMap(t, path, cfg, 100, 200)
92		setTrajectoryTimes(t, path, 0, 1000, 2000)
93		m, err := Open(path)
94		if err != nil {
95			t.Fatalf("open: %v", err)
96		}
97		if p, err := m.PoseAt(1500); err != nil || p.Time != 1000 {
98			t.Fatalf("PoseAt(1500) = %+v %v", p, err)
99		}
100		if err := m.Close(); err != nil {
101			t.Fatal(err)
102		}
103	
104		empty := filepath.Join(t.TempDir(), "empty.pose")
105		buildTimedMap(t, empty, cfg)
106		m, err = Open(empty)
107		if err != nil {
108			t.Fatalf("open initial-only map: %v", err)
109		}
110		if p, err := m.CurrentPose(); err != nil || p.Time != 0 {
111			t.Fatalf("CurrentPose = %+v %v", p, err)
112		}
113		m.Close()
114	}
