116	// 时间差按真实数学差值判断：初始时间 MinInt64、MaxInterval 取 MaxInt64
117	// 时，跳到 0 的真实间隔为 2^63，超过上限必须拒绝；跳到 -1 的间隔恰好
118	// 等于上限，应当允许。
119	func TestOpenTrajectoryIntervalOverflow(t *testing.T) {
120		cfg := Config{InitialTime: math.MinInt64, MaxInterval: math.MaxInt64, MergeDistance: 1.0}
121	
122		path := filepath.Join(t.TempDir(), "m.pose")
123		buildTimedMap(t, path, cfg, -1)
124		setTrajectoryTimes(t, path, math.MinInt64, 0)
125		if m, err := Open(path); !errors.Is(err, ErrCorrupt) || m != nil {
126			t.Fatalf("MinInt64 -> 0: err = %v, map = %v, want ErrCorrupt and nil map", err, m)
127		}
128	
129		ok := filepath.Join(t.TempDir(), "ok.pose")
130		buildTimedMap(t, ok, cfg, -1)
131		m, err := Open(ok)
132		if err != nil {
133			t.Fatalf("MinInt64 -> -1: %v", err)
134		}
135		if p, err := m.CurrentPose(); err != nil || p.Time != -1 {
136			t.Fatalf("CurrentPose = %+v %v", p, err)
137		}
138		m.Close()
139	}
140	
141	// 缺少逐帧来源的旧文件同样要满足时间规则：时间异常即拒绝；时间正常时
142	// 不因来源缺失被拒绝，原有查询与继续导入保持可用。
143	func TestOpenLegacyFileTrajectoryTimes(t *testing.T) {
144		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
