152		if m, err := Open(bad); !errors.Is(err, ErrCorrupt) || m != nil {
153			t.Fatalf("legacy bad times: err = %v, map = %v, want ErrCorrupt and nil map", err, m)
154		}
155	
156		good := filepath.Join(t.TempDir(), "good.pose")
157		buildTimedMap(t, good, cfg, 100, 200)
158		fd = readFileData(t, good)
159		fd.Sources = nil
160		writeFileDataRaw(t, good, &fd)
161		m, err := Open(good)
162		if err != nil {
163			t.Fatalf("legacy open: %v", err)
164		}
165		defer m.Close()
166		if p, err := m.PoseAt(150); err != nil || p.Time != 100 {
167			t.Fatalf("PoseAt(150) = %+v %v", p, err)
168		}
169		if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{{Time: 300, DX: 1}}}); err != nil {
170			t.Fatalf("legacy continue import: %v", err)
171		}
172	}
